"""Begin editing native categorical splits, preserving numeric derivations."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Numeric split имеет вид':r'''Числовое разбиение проверяет $x<t$, а категориальное может проверять принадлежность $c\in S$, где $S$ — подмножество категорий. Пусть эффекты A/B/C/D равны (1,−1,1,−1), а произвольные коды — 1/2/3/4. Один числовой порог не отделит A/C от B/D, но проверка принадлежности множеству отделит. Передать коды как обычные числа и объявить поле категориальным — разные операции.''',
'Полный перебор бинарных partitions':r'''Полный перебор нетривиальных бинарных разделений $K$ категорий с учётом симметрии сторон требует $2^{K-1}-1$ вариантов. Для некоторых скалярных целей можно отсортировать категории по статистике листа и проверять границы в этом порядке. Порядок вычисляют в текущем узле по целевой функции; это не исходный порядок ID.''',
'При second-order boosting node':r'''В схеме бустинга второго порядка узел накапливает сумму градиентов $G$ и сумму вторых производных $H$. Типичное значение скалярного листа равно $-G/(H+\lambda)$. При подходящих предположениях категории с близкими ответами листа можно объединять. Для векторного выхода универсального скалярного порядка нет; выбор приближения зависит от реализации. Доказательство для скалярных листьев нельзя автоматически переносить на любую цель.''',
'На очередном boosting step':r'''На очередном шаге бустинга уже есть предсказания $f_i$. Для дифференцируемой потери вычисляют $g_i=\partial\ell(y_i,f_i)/\partial f_i$ и $h_i=\partial^2\ell(y_i,f_i)/\partial f_i^2$. Для половины квадрата ошибки $g_i=f_i-y_i$, $h_i=1$; для бинарной логистической потери по логиту $g_i=p_i-y_i$, $h_i=p_i(1-p_i)$. Поэтому агрегаты градиентов в общем случае не равны средним исходной цели: они зависят от текущих предсказаний предыдущих деревьев.''',
'Если всем объектам leaf назначить':r'''Если всем объектам листа назначить скалярную добавку $w$, зависящая от неё часть приближения цели второго порядка имеет вид:''',
'При $H+\\lambda>0$ derivative':r'''При $H+\lambda>0$ производная $G+(H+\lambda)w=0$ даёт $w^*=-G/(H+\lambda)$ и минимум $-G^2/[2(H+\lambda)]$. Здесь $\lambda$ — L2-штраф веса листа при суммировании потерь. Усреднение, веса строк и другие нормировки меняют сопоставимый масштаб штрафа. Для негладких функций или иных приближений второй производной вывод надо сверять с конкретным алгоритмом.''',
'Для split с children L/R':'''Выигрыш разбиения на левый и правый листы относительно одного родительского листа равен''',
'Gamma здесь — дополнительная стоимость':r'''Здесь $\gamma$ — дополнительная стоимость одного листа при переходе от одного листа к двум. Это учебная схема второго порядка: библиотеки могут использовать другой масштаб выигрыша и другие настройки. Шаг обучения обычно применяют к найденным добавкам после построения дерева; точное изменение исходной потери после уменьшения добавок не обязано равняться первоначальному выигрышу.''',
'Пусть в текущем node у A/B/C/D':r'''Пусть в текущем узле для каждой из категорий A/B/C/D есть по две строки со второй производной 1. Градиенты каждой строки внутри категорий равны соответственно −2, 1, −1, 2. Суммы $G$ по категориям — (−4,2,−2,4), суммы $H$ — (2,2,2,2). При $\lambda=1$, $\gamma=0$ у родителя $G=0,H=8$, поэтому его вес равен 0.''',
'При numeric codes A=1':r'''При числовых кодах A=1,B=2,C=3,D=4 доступны только три порога. Для A|BCD выигрыш равен $(16/3+16/7)/2=80/21\approx3.8095$. Для AB|CD — $(4/5+4/5)/2=0.8$. Для ABC|D снова получается 80/21. Ни один порог не создаёт AC|BD.''',
'Categorical subset AC имеет':r'''Подмножество AC имеет $G=-6,H=4$, дополнение BD — $G=6,H=4$. Веса листьев равны 1.2 и −1.2, выигрыш — $(36/5+36/5)/2=7.2$. При $\gamma=0.5$ он снижается до 6.7. При шаге обучения 0.1 добавки к предсказанию составят +0.12 и −0.12; это не обещание, что исходная потеря после уменьшения добавок снизится ровно на 7.2.''',
'Для K=4 существует семь':r'''Для $K=4$ есть семь нетривиальных бинарных разбиений без учёта порядка сторон, для $K=20$ — 524 287. Формула $2^{K-1}-1$ получается из всех подмножеств после исключения пустого и полного и отождествления каждой пары дополнений. Сами ID категорий не задают полезного порядка для поиска.''',
'Для подходящих scalar objectives':'''Для подходящих скалярных целей категории можно упорядочить по статистике ответа и проверить K−1 границ в этом порядке. В нашем примере индивидуальные регуляризованные ответы листа равны A=4/3, B=−2/3, C=2/3, D=−4/3. Порядок D,B,C,A приводит к нужному разбиению DB|CA посередине. Он отличается от исходного порядка кодов A,B,C,D.''',
'Слово «optimal» относится':'''Слово «оптимальный» относится к определённой задаче, разрешённым разбиениям и предположениям теоремы. L1/L2-штрафы, ограничения на дочерние узлы, сглаживание категорий, сокращённый список кандидатов и векторные выходы нельзя автоматически включать в доказательство без проверки. Средняя исходная метка по всему набору также не является универсальной заменой порядку по градиентам текущего узла.''',
}
def op(t):
 for prefix,new in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+new+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-native.md',op,
 'Пакет 03: редактура категориального разбиения и вывода весов листьев с сохранением вычислений; приёмка ожидается.',c);save(c)
print('Native categorical split draft edited; chapter review remains open.')
